class Solution:
    def verticalTraversal(self, root: Optional[TreeNode]) -> list[list[int]]:
        nodes = []
        def dfs(node: Optional[TreeNode], r: int, c: int):
            if not node:
                return
            nodes.append((c, r, node.val))
            dfs(node.left, r + 1, c - 1)
            dfs(node.right, r + 1, c + 1)
        dfs(root, 0, 0)
        nodes.sort()
        res = []
        last_c = None
        for c, r, val in nodes:
            if c != last_c:
                res.append([])
                last_c = c
            res[-1].append(val)
        return res

class Solution {
public:
    vector<vector<int>> verticalTraversal(TreeNode* root) {
        vector<tuple<int, int, int>> nodes;
        auto dfs = [&](auto& self, TreeNode* node, int r, int c) -> void {
            if (!node) return;
            nodes.push_back({c, r, node->val});
            self(self, node->left, r + 1, c - 1);
            self(self, node->right, r + 1, c + 1);
        };
        dfs(dfs, root, 0, 0);
        sort(nodes.begin(), nodes.end());
        vector<vector<int>> res;
        int last_c = INT_MIN;
        for (const auto& [c, r, val] : nodes) {
            if (res.empty() || c != last_c) {
                res.push_back({});
                last_c = c;
            }
            res.back().push_back(val);
        }
        return res;
    }
};

class Solution {
    private List<int[]> nodes = new ArrayList<>();
    private void dfs(TreeNode node, int r, int c) {
        if (node == null) return;
        nodes.add(new int[]{c, r, node.val});
        dfs(node.left, r + 1, c - 1);
        dfs(node.right, r + 1, c + 1);
    }
    public List<List<Integer>> verticalTraversal(TreeNode root) {
        dfs(root, 0, 0);
        nodes.sort((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            if (a[1] != b[1]) return Integer.compare(a[1], b[1]);
            return Integer.compare(a[2], b[2]);
        });
        List<List<Integer>> res = new ArrayList<>();
        Integer lastC = null;
        for (int[] n : nodes) {
            if (lastC == null || n[0] != lastC) {
                res.add(new ArrayList<>());
                lastC = n[0];
            }
            res.get(res.size() - 1).add(n[2]);
        }
        return res;
    }
}

var verticalTraversal = function(root) {
    const nodes = [];
    const dfs = (node, r, c) => {
        if (!node) return;
        nodes.push([c, r, node.val]);
        dfs(node.left, r + 1, c - 1);
        dfs(node.right, r + 1, c + 1);
    };
    dfs(root, 0, 0);
    nodes.sort((a, b) => {
        if (a[0] !== b[0]) return a[0] - b[0];
        if (a[1] !== b[1]) return a[1] - b[1];
        return a[2] - b[2];
    });
    const res = [];
    let lastC = null;
    for (const [c, r, val] of nodes) {
        if (c !== lastC) {
            res.push([]);
            lastC = c;
        }
        res[res.length - 1].push(val);
    }
    return res;
};
